certificates.type:
∀ (I : Sort u) (T : I → Sort v) (U : (i : I) → T i → Sort w) (f : (i : I) → PSigma.{v, w} (U i)),
  Eq.{max (max 1 (imax u v)) (imax u w)}
    (Computational.SSRFun.NativeBridge.Incremental.SSRFunData.sigmaTo.{imax u v, imax u w}
      (Computational.SSRFun.Rocq.Corelib.ssr.ssrfun.all_tag.{u, v, w} I T U fun i =>
        Computational.SSRFun.NativeBridge.Incremental.SSRFunData.sigmaOf.{v, w} (f i)))
    (NativeBridge.ComputationalCorrespondence.SSRFun.allTag.{u, v, w} I T U f)

∀ (I : Sort u) (T : I → Sort v) (P : (i : I) → T i → Prop) (f : (i : I) → Subtype.{v} (P i)),
  Eq.{max 1 (imax u v)}
    (Computational.SSRFun.NativeBridge.Incremental.SSRFunNormalization.sigTo.{imax u v}
      (Computational.SSRFun.RocqPending.Corelib.ssr.ssrfun.all_sig.{u, v} I T P fun i =>
        Computational.SSRFun.NativeBridge.Incremental.SSRFunNormalization.sigOf.{v} (f i)))
    (NativeBridge.ComputationalCorrespondence.SSRFun.allSig.{u, v} I T P f)

∀ (I : Sort u) (T : I → Sort v) (P Q : (i : I) → T i → Prop) (f : (i : I) → Subtype.{v} fun a => P i a ∧ Q i a),
  Eq.{max 1 (imax u v)}
    (Computational.SSRFun.NativeBridge.Incremental.SSRFunNormalization.sig2To.{imax u v}
      (Computational.SSRFun.RocqPending.Corelib.ssr.ssrfun.all_sig2.{u, v} I T P Q fun i =>
        Computational.SSRFun.NativeBridge.Incremental.SSRFunNormalization.sig2Of.{v} (f i)))
    (NativeBridge.ComputationalCorrespondence.SSRFun.allSig2.{u, v} I T P Q f)
